WITH filtered_inventory AS (SELECT *, LAST_DAY(last_restock) AS last_restock_month_end FROM inventory WHERE quantity BETWEEN 64 AND 177), agg AS (SELECT CASE WHEN quantity >= 259 THEN 'high' WHEN quantity >= 111 THEN 'mid' ELSE 'low' END AS quantity_bucket, AVG(quantity) AS avg_quantity FROM filtered_inventory GROUP BY CASE WHEN quantity >= 259 THEN 'high' WHEN quantity >= 111 THEN 'mid' ELSE 'low' END) SELECT quantity_bucket, avg_quantity FROM agg ORDER BY avg_quantity DESC, quantity_bucket LIMIT 5;
